const perms = {
  admin: ["user:delete"],
  manager: ["report:approve"],
  editor: ["post:write"],
  viewer: ["post:read"],
};

function effective(role, acc = new Set()) {
  perms[role].forEach((p) => acc.add(p));
  inherits[role].forEach((r) => effective(r, acc));
  return acc;
}

